'QZ_Tray_Printer' => 'QZ Tray (skriver på denne datamaskinen)',
'QZ_Printer_Name_Hint' => 'Skrivernavnet slik det vises på datamaskinen som kjører QZ Tray. La stå tomt for å bruke datamaskinens standardskriver. Klikk ⟳ for å finne skrivere.',
