'QZ_Setup_Title' => 'Slik setter du opp QZ Tray-utskrift (én gang, på hver datamaskin som skriver ut etiketter)',
'QZ_Step_Install' => '1. Installer QZ Tray på denne datamaskinen — last det ned gratis fra qz.io, start det og la det kjøre (det ligger i systemstatusfeltet på Windows eller i menylinjen på macOS).',
'QZ_Step_Connect' => '2. Koble etikettskriveren til via USB og kontroller at den er installert i operativsystemet (Windows: Innstillinger > Skrivere og skannere — macOS: Systeminnstillinger > Skrivere og skannere).',
'QZ_Step_Detect' => '3. Klikk ⟳-knappen ved siden av «Skrivernavn» ovenfor for å finne skriverne på denne datamaskinen, og velg deretter etikettskriveren. La feltet stå tomt for å bruke datamaskinens standardskriver.',
'QZ_Step_Cert' => '4. For utskrift uten tillatelsesvindu, last ned sertifikatet nedenfor og kopier det til installasjonsmappen for QZ Tray med nytt navn override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Avslutt deretter QZ Tray og start det på nytt.',
'QZ_Step_Test' => '5. Klikk «Skriv ut testetikett» nedenfor. Hvis QZ Tray ber om tillatelse, klikk Tillat — med sertifikatet installert spør det ikke igjen.',
'QZ_Step_Save' => '6. Klikk Send inn for å lagre innstillingene. Etiketter fra siden Skriv ut strekkode skrives nå ut direkte på denne skriveren, uten nettleserens utskriftsdialog.',
'QZ_Setup_Note' => 'QZ Tray kjører på datamaskinen du surfer fra, så dette fungerer selv når Stocky er hostet på en ekstern server. Hver datamaskin som skriver ut etiketter, må ha QZ Tray installert.',
