'Ord_Guide_Payment_Title' => 'Betalingsstatus',
'Ord_Guide_Payment_Intro' => 'Denne kolonnen registrerer hvordan kunden valgte å betale i kassen. Den angis av nettbutikken og kan ikke redigeres fra denne siden — selve pengene spores på salget som opprettes når ordren bekreftes.',
'Ord_Guide_Payment_Paid' => 'Kunden har allerede betalt på nett via en betalingsløsning. Når ordren bekreftes, opprettes salget som Betalt og betalingen registreres for deg — du trenger ikke gjøre noe mer.',
'Ord_Guide_Payment_Pending' => 'Betaling ved levering, bankoverføring eller en annen betal-senere-metode. Når ordren bekreftes, opprettes salget som Ubetalt, så du registrerer pengene selv når du har mottatt dem — se trinnene nedenfor.',
