'Ord_Guide_MarkPaid_Step4' => 'Angi beløp, betalingsmetode og dato, og lagre. Salget går automatisk til Delvis eller Betalt, avhengig av beløpet.',
'Ord_Guide_MarkPaid_Note' => 'Betalingsstatusen som vises her, fortsetter å registrere valget fra kassen og forblir uendret. Salget er regnskapsposten, og det er dette som mater betalings- og fortjenesterapportene dine. Bruk Vis betalinger på salget for å se gjennom eller redigere det du registrerte.',
'Ord_Guide_Notes_Title' => 'Greit å vite',
