'Upd_Validation_Runs_Automatically' => 'Validering kjøres automatisk',
'Upd_Guide_Run_Review' => 'Se gjennom panelet {panel}. Knappen {button} vises bare når alle kritiske kontroller er bestått. Hvis en kontroll mislykkes, forteller meldingen nøyaktig hva som må rettes.',
'Upd_Guide_Run_Click' => 'Klikk {button} og bekreft. Deretter er det bare å {keep} og følge fremdriftslinjen. Systemet utfører, i rekkefølge:',
'Upd_Keep_Page_Open' => 'holde denne siden åpen',
'Upd_Guide_Phase_Backup' => '{label} — en full databasedump, en ZIP av alle applikasjonsfiler oppdateringen kan endre, og en kopi av {env} opprettes og {verified}. Opplastingene dine ({images}) og {storage} røres aldri av en oppdatering, så de arkiveres ikke. Hvis en sikkerhetskopi ikke kan opprettes, stopper oppdateringen her og ingenting endres.',
'Upd_Verified' => 'verifiseres',
'Upd_Guide_Phase_Prepare' => '{label} — den nye versjonen pakkes ut i et klargjøringsområde og valideres på nytt. Den aktive applikasjonen er fortsatt urørt.',
'Upd_Guide_Phase_Maintenance' => '{label} — vedlikeholdsmodus aktiveres; besøkende ser en vennlig «Vi er straks tilbake»-skjerm.',
'Upd_Guide_Phase_Files' => '{label} — de nye filene byttes inn nesten umiddelbart; de gamle filene holdes til side for tilbakerulling. Beskyttede stier ({env}, {storage}, {images}) erstattes aldri.',
'Upd_Guide_Phase_Database' => '{label} — migreringer kjøres, deretter oppdateres tillatelser, oversettelser og maler.',
'Upd_Guide_Phase_Cache' => '{label} — alle hurtigbuffere tømmes og bygges på nytt.',
'Upd_Guide_Phase_Verify' => '{label} — helsesjekker bekrefter at den nye versjonen starter, at databasen fungerer, at alle migreringer er kjørt og at konfigurasjonen er gyldig.',
'Upd_Guide_Phase_Done' => '{label} — vedlikeholdsmodus oppheves og midlertidige filer ryddes bort.',
'Upd_Guide_Run_Success' => 'Når du ser {success}, klikk {reload} og gjør en hard oppdatering av nettleseren ({keys}) slik at de nye ressursene for administrasjonspanelet lastes.',
'Upd_Update_Successful_Short' => 'Oppdatering vellykket',
'Upd_Guide_No_Internet' => 'Ingen internettilkobling trengs under oppdateringen — alt kommer fra den opplastede ZIP-filen. Å miste tilkoblingen eller lukke nettleseren ødelegger IKKE oppdateringen: serveren husker nøyaktig hvor den stoppet.',
'Upd_Guide_Wrong_Title' => '3. Hvis noe går galt',
'Upd_Guide_Wrong_Rollback' => '{label} — hvis noe mislykkes etter at filene begynte å endres (utpakkingsfeil, migreringsfeil, mislykket helsesjekk, full disk, …), gjenoppretter systemet automatisk de forrige filene og databasen fra den verifiserte sikkerhetskopien, opphever vedlikeholdsmodus og rapporterer {message}. Du ender opp nøyaktig der du startet.',
'Upd_Automatic_Rollback' => 'Automatisk tilbakerulling',
'Upd_Failed_Previous_Restored' => 'Oppdatering mislyktes — forrige versjon gjenopprettet',
'Upd_Guide_Wrong_Interrupted' => '{label} (omstart av server, tidsavbrudd, lukket nettleser, strømbrudd) — når du åpner denne siden igjen, tilbyr et rødt banner to trygge valg: {resume} (fortsetter fra nøyaktig det trinnet der den stoppet) eller {rollback} (gjenoppretter forrige versjon fra sikkerhetskopien).',
'Upd_Interrupted_Update' => 'Avbrutt oppdatering',
'Upd_Guide_Wrong_Unreachable' => '{label} — bruk den frittstående {console} på {path}. Den fungerer selv når nettstedet er i vedlikeholdsmodus eller ressursene for administrasjonspanelet er ødelagt, og tilbyr de samme handlingene Fortsett / Rull tilbake. Det finnes også en diskret «Administratortilgang»-lenke nederst på vedlikeholdsskjermen.',
'Upd_Admin_Unreachable' => 'Administrasjonspanelet er utilgjengelig',
'Upd_Recovery_Console' => 'gjenopprettingskonsollen',
'Upd_Guide_Wrong_Locked_Out' => '{label} — mens en oppdatering kjører, viser denne siden en {link}. Lagre den hvis du trenger å komme inn igjen (for eksempel etter at økten din har utløpt); den slipper deg forbi vedlikeholdsskjermen slik at du kan logge inn på nytt.',
'Upd_Locked_Out_Maintenance' => 'Stengt ute av vedlikeholdsmodus',
'Upd_Bypass_Link' => 'omgåelseslenke',
'Upd_Guide_Wrong_Concurrent' => '{label} — de vil se {message} Bare én oppdatering kan kjøre om gangen.',
'Upd_Another_Admin_Updating' => 'En annen administrator prøver å oppdatere samtidig',
'Upd_Guide_Backups_Title' => '4. Sikkerhetskopier og gjenoppretting',
'Upd_Guide_Backups_Created' => 'Hver oppdatering lager en sikkerhetskopi {before} noe endres: alle applikasjonsfiler oppdateringen kan erstatte, en kopi av {env} og en full databasedump. Opplastinger og {storage} endres aldri av en oppdatering og er derfor ikke med — ta dine egne sikkerhetskopier av disse. Sikkerhetskopiene ligger i {path} og er aldri tilgjengelige fra nettet.',
'Upd_Before' => 'før',
'Upd_Guide_Backups_Panel' => 'Panelet {panel} på fanen {tab} viser dem med dato, versjon og størrelse. Derfra kan du {restore} en hvilken som helst fullstendig sikkerhetskopi (filer + database — en sikkerhetskopi av gjeldende database tas først) eller {delete} gamle.',
'Upd_Restore_Verb' => 'gjenopprette',
'Upd_Delete_Verb' => 'slette',
'Upd_Guide_Backups_Retention' => 'Bruk {keep} til å velge hvor mange sikkerhetskopier som beholdes; eldre fjernes automatisk etter hver vellykket oppdatering. Den eneste gjenværende fullstendige sikkerhetskopien kan aldri slettes — du har alltid en vei tilbake.',
'Upd_Guide_Manual_Title' => '5. Manuell oppdatering (reservemetode)',
'Upd_Guide_Manual_Text' => 'Hvis du foretrekker å oppdatere manuelt, eller opplastingsverktøyet ikke kan brukes på serveren din, følg trinn-for-trinn-instruksjonene på fanen {tab} på denne siden.',
'Upd_Guide_Clear_Cache_First' => 'Hvis sider ser ødelagte eller tomme ut etter en oppdatering, tøm nettleserens hurtigbuffer først — det er nesten alltid årsaken.',
'Upd_Restore_Backup_Confirm' => 'Gjenopprette denne sikkerhetskopien? Gjeldende filer og gjeldende database erstattes av sikkerhetskopien. En sikkerhetskopi av gjeldende database tas først. (v{version} — {date})',
'Woo_Guide_Lead' => 'Hvordan en WooCommerce-butikk holder seg i takt med ERP-systemet. Cron-linjene nedenfor er laget for denne serveren, så de kan kopieres rett inn.',
'Woo_Guide_Ways_Note' => 'I motsetning til Shopify sender ikke WooCommerce noe til ERP-systemet av seg selv — det finnes ingen webhook-mottaker her, så alt som kommer {in} ankommer etter tidsplanen. Bare lager som går {out} kan være umiddelbart.',
'Woo_In' => 'inn',
'Woo_Out' => 'ut',
'Woo_Guide_Both_Ways_Title' => 'Begge retninger trenger dette først',
'Woo_Api_Keys' => 'API-nøkler',
'Woo_Guide_Api_Keys_Text' => '{path}, tillatelse {perm}. Kopier consumer key og secret inn i fanen {settings}, sammen med butikkens URL — nettstedets adresse uten avsluttende skråstrek, f.eks. {example}.',
'Woo_Credentials_Saved' => 'legitimasjon lagret',
'Woo_Not_Configured_Yet' => 'ikke konfigurert ennå',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress-applikasjonspassord (valgfritt)',
'Woo_Guide_Wp_App_Password_Text' => 'Brukes bare for produktbilder. WooCommerce-API-et flytter produkter, lager, kategorier, merker, kunder og ordrer; WordPress-API-et er det som søker i mediebiblioteket og laster opp et bilde som ikke finnes der ennå.',
'Woo_Guide_Wp_App_Password_Note' => 'Bruk en WordPress-bruker som kan administrere medier, og opprett passordet under {path}. La begge feltene stå tomme, og alt synkroniseres fortsatt — bare bildevedlegg hoppes over.',
'Woo_Guide_Pick_Way_Title' => 'Velg deretter hvordan den holder seg i takt',
'Woo_Right_Away' => 'Umiddelbart',
'Woo_Stock_Live' => 'lager i sanntid',
'Woo_Stock_Not_Live' => 'lager ikke i sanntid',
'Woo_Guide_Realtime_Lead' => 'Bare én retning: lager og produkter som forlater ERP-systemet. Ordrer og produktendringer gjort i WooCommerce kommer fortsatt etter tidsplanen — se den andre fanen.',
'Woo_Push_Stock_On_Change' => 'Overfør lager i det øyeblikket det endres',
'Woo_Setting_People_Miss' => 'Dette er innstillingen folk overser',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Et POS-salg {not} WooCommerce av seg selv. Hvis dette er av, får butikken først vite det ved neste lagersynkronisering — som standard en time — og i det vinduet kan den selge en enhet du allerede har solgt i kassen.',
'Woo_Does_Not' => 'når ikke frem til',
'Woo_Guide_Tick_Instant' => 'Kryss av for {option} på fanen {settings}. Det er hele oppsettet — ingen worker, ingen cron. Hvert salg, hver retur, justering, overføring og mottatt innkjøp sender da en overføring av bare de produktene, rett etter at salget er lagret, og et salg med tjue linjer koster én overføring, ikke tjue. Kassen venter aldri på den.',
'Woo_Currently' => 'Nå:',
'Woo_Instant_On_Text' => 'på — lager overføres ved endring',
'Woo_Instant_Off_Text' => 'av — lager kun etter tidsplan',
'Woo_Guide_Instant_Note' => 'Bare produkter som allerede er koblet til WooCommerce, overføres — et produkt som aldri har blitt synkronisert, har ingenting i butikken å korrigere. Variable produkter går via sitt overordnede produkt, og en kombinasjon overføres på nytt når noen av komponentene endres. Masseoperasjoner (slette et produkt, tilbakestille et lager) skriver lager uten å utløse en hendelse, noe som er en grunn til å beholde den timevise lagersynkroniseringen også.',
'Woo_Push_Products_On_Save' => 'Overfør produkter i det øyeblikket de lagres',
'Woo_Guide_Tick_Auto_Products' => 'Kryss av for {option} på fanen {settings}, så sendes et produkt som opprettes, redigeres eller dupliseres i Stocky til WooCommerce rett etter at det er lagret — detaljer, pris, varianter og bilder, deretter lageret. Et nytt produkt opprettes i butikken med en gang i stedet for å vente på den nattlige produktsynkroniseringen.',
'Woo_On' => 'på',
'Woo_Off' => 'av',
'Woo_Guide_Bulk_Imports_Note' => 'Masseimporter overføres ikke én etter én — kjør en produktsynkronisering etter en import. Synkroniser kategorier og merker først, slik at et overført produkt havner i riktig kategori.',
'Woo_Nothing_Else_To_Install' => 'Ingenting annet å installere',
'Woo_Guide_Same_Process' => 'Ingen kø-worker, ingen cron-oppføring. Overføringen kjører i den samme prosessen som betjente salget, {after} at svaret er sendt tilbake, så kassen venter aldri på WooCommerce. Overføringer overlapper aldri: endringer gjort mens én kjører, venter på den og sendes rett etterpå.',
'Woo_After' => 'etter',
'Woo_Guide_Shop_Stops_Answering' => 'En butikk som slutter å svare, gis opp etter åtte sekunder, og overføringer settes på pause i fem minutter slik at ikke hvert salg venter på den igjen; endringene som kom inn i mellomtiden, sendes med den første overføringen etter pausen, og den timevise lagersynkroniseringen tar igjen uansett. Hver pause registreres i fanen Logger.',
'Woo_Guide_Artisan_Exception' => 'Ett unntak: en lagerendring gjort av en artisan-kommando har ikke noe svar å komme etter, så den settes i kø på {queue} i stedet. For at også disse skal sendes raskt, tøm den køen:',
'Woo_Cron_Line_Copied' => 'Cron-linje kopiert',
'Woo_Command_Copied' => 'Kommando kopiert',
'Woo_Guide_Not_Woo_Queue' => 'Bevisst ikke {queue}-køen: den bærer de timelange katalogbatchene, og en umiddelbar overføring i kø bak en av dem ville ikke vært umiddelbar.',
'Woo_On_A_Schedule' => 'Etter tidsplan',
'Woo_Guide_Scheduled_Lead' => 'Alt kontrolleres på nytt med jevne mellomrom, begge veier. Det er slik ordrer når ERP-systemet, hvordan en katalog publiseres, og hva som reparerer alt den raske veien gikk glipp av. Hver jobb får sin egen cron-oppføring, så du kjører bare det du ønsker.',
'Woo_Guide_Sync_Drains_Queue' => '{command} tømmer sin egen kø mens den kjører, så disse linjene trenger ingen separat worker. På Windows, bruk Oppgaveplanlegging med programmet {program} og de samme argumentene, startet i {path}.',
'Woo_Or_No_Cron' => 'Eller ingen cron i det hele tatt',
'Woo_Guide_No_Cron_Text' => 'Hver fane her synkroniserer ved behov, og en manuell synkronisering tømmer sine egne batcher mens siden er åpen — så en liten butikk kan kjøre uten noen cron-oppføring i det hele tatt. Det du mister, er alt som skjer mens ingen ser: ordrer kommer bare når noen trykker på knappen.',
'Woo_Commands_Worth_Knowing' => 'Kommandoer verdt å kjenne',
'Woo_Worth_Knowing' => 'Verdt å vite',
'Woo_Guide_Changing_Url_Clears' => 'Endring av butikkens URL eller API-nøklene fjerner alle koblinger — produkter, kategorier, merker og kunder synkroniseres alle på nytt til den nye butikken.',
'Woo_Guide_Keep_Skus' => 'Hold SKU-er konsistente mellom Stocky og WooCommerce: det er det som hindrer duplikater og gjør ny kobling trygg.',
'Woo_Guide_Stock_Total' => 'Lageret som publiseres til Woo, er {total}, ikke tallet for ett lager.',
'Woo_Total_Across_Warehouses' => 'totalen på tvers av alle lagre',
'Woo_Guide_Full_Reference' => 'Den fullstendige referansen — alle omfang, hvordan køen oppfører seg, og en feilsøkingsliste — finnes i {file}.',
'Woo_Way_Covers' => 'Dekker',
'Woo_Way_Covers_Realtime' => 'Bare lager som forlater ERP-systemet — et POS-salg, en retur, en justering, et mottatt innkjøp',
'Woo_Way_Covers_Scheduled' => 'Alt, begge veier: ordrer og produktendringer inn, katalog og lager ut',
'Woo_Way_Speed' => 'Hastighet',
'Woo_Way_Seconds' => 'Sekunder',
'Woo_Way_Speed_Scheduled' => 'Det du angir i cron-oppføringen (lager hver time, ordrer hvert 15. min)',
'Woo_Way_Needs' => 'Krever',
