'Woo_Way_Needs_Scheduled' => 'En cron-oppføring per jobb — eller ingenting, hvis du synkroniserer manuelt',
'Woo_Way_Switched_On_At' => 'Slås på i',
'Woo_Way_Cron_Entries_Below' => 'Cron-oppføringene nedenfor',
'Woo_Cron_Orders' => 'Ordrer hvert 15. minutt — bare de som er endret siden forrige kjøring.',
'Woo_Cron_Products_Pull' => 'Produktendringer fra butikken, hver natt kl. 03:00.',
'Woo_Cron_Customers' => 'Kunder, hver natt kl. 03:30.',
'Woo_Cron_Stock' => 'Lager hver time — sikkerhetsnettet under umiddelbar overføring, og den eneste lagersynkroniseringen uten den.',
'Woo_Cron_Products_Push' => 'Produkter som ennå ikke er koblet, hver natt kl. 02:00. Eksisterende produkter skrives ikke om.',
'Woo_Cmd_Stock' => 'Overfør lager for alle koblede produkter nå.',
