'Woo_Cmd_Orders_Full' => 'Skann alle ordrer på nytt i stedet for bare nylige endringer.',
'Woo_Cmd_Pull' => 'Alt innkommende på en gang: produkter, ordrer, kunder.',
'Woo_Guide_Page_Title' => 'WooCommerce-veiledning',
'Woo_Guide_Page_Subtitle' => 'Tilkobling av butikken, hva som kjører av seg selv, og cron-oppføringene for denne serveren',
'Woo_Settings_Button' => 'WooCommerce-innstillinger',
'Woo_No_Shop_Connected' => 'Ingen butikk er tilkoblet ennå',
'Woo_No_Shop_Connected_Desc' => 'Alt nedenfor gjelder fortsatt — angi butikkens URL og API-nøkler på siden for WooCommerce-innstillinger, og kom deretter tilbake.',
'Woo_Wp_Username' => 'WordPress-brukernavn',
'Woo_Wp_App_Password' => 'WordPress-applikasjonspassord',
'Woo_Settings_Instant_Hint' => 'Et salg, en retur eller en justering sender en lageroverføring av bare de produktene i det øyeblikket det lagres, så butikken er korrekt i løpet av sekunder i stedet for ved neste timevise lagersynkronisering. Ingenting annet å installere — overføringen kjører etter at salget er besvart, så kassen venter aldri på WooCommerce. Mer på fanen {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Hvis dette er av, når et POS-salg WooCommerce først ved neste lagersynkronisering — opptil en time senere.',
'Woo_Settings_Auto_Products_Hint' => 'Et produkt som opprettes, redigeres eller dupliseres i Stocky, sendes til WooCommerce rett etter at det er lagret — detaljer, pris, varianter, bilder, deretter lageret — i stedet for å vente på en produktsynkronisering. Masseimporter overføres ikke; kjør en produktsynkronisering etter en import.',
'Woo_Sync_Tuning' => 'Finjustering av synkronisering',
'Woo_Sync_Tuning_Intro' => 'Standardverdiene passer de fleste butikker. Endre disse bare hvis synkroniseringen er treg eller får tidsavbrudd på din hosting. Hver verdi begrenses til et trygt område, og å tømme et felt gjenoppretter standardverdien.',
'Woo_Setting_This_Up' => 'Oppsett',
'Woo_Setting_This_Up_Text' => 'Hvordan du får API-nøklene, hva WordPress-applikasjonspassordet er til, cron-oppføringene for planlagte synkroniseringer, og hvordan lageret når butikken i det øyeblikket det endres — alt dette, med denne serverens egne cron-linjer klare til å kopieres, finnes på fanen Veiledning. Én kopi, så den kan ikke avvike fra hva modulen faktisk gjør.',
