'Telegram_G_A_Body' => 'Et salg, innkjøp, en betaling eller utgift som lagres i Stocky — i POS eller i administrasjonen — sendes til Telegram {after} at det er lagret, i samme forespørsel. Ingen cron-oppføring, ingen kø-worker, og kassereren venter aldri på Telegram: salget er allerede besvart når meldingen går ut.',
