'Shopify_Hook_Note_Register' => 'Registrering oppretter abonnementene i Shopify og peker dem automatisk mot denne adressen. Ikke legg den til manuelt under Shopify → Settings → Notifications → Webhooks: disse signeres med en annen hemmelighet, og hver leveranse ville bli avvist.',
