'Shopify_Could_Not_Remove_Sub' => 'Kunne ikke fjerne det abonnementet',
'Shopify_Could_Not_Load_Store' => 'Kunne ikke laste denne butikken',
'Shopify_G_Lead_Store' => 'Hva denne butikken trenger for å holde seg i takt. Alt her er spesifikt for denne butikken — stiene og id-ene er ekte, så kommandoene kan kopieres rett inn på serveren.',
'Shopify_G_Lead_Generic' => 'Hvordan en Shopify-butikk holder seg i takt med ERP-systemet. Velg en butikk ovenfor for å se dens egen tilstand, eller les det som det er — cron-linjen og webhook-URL-en er de samme uansett hvilken butikk du kobler til.',
'Shopify_G_Ways_Note' => 'De fleste butikker kjører begge: den første holder butikken oppdatert minutt for minutt, den andre fanger opp det den første gikk glipp av — en webhook som aldri kom, en endring gjort direkte i Shopify admin, en natt da nettstedet var nede.',
'Shopify_G_Both_Need' => 'Begge retninger trenger dette først',
'Shopify_G_Credentials' => 'Shopify-legitimasjon',
'Shopify_G_Cred_Intro' => 'Siden januar 2026 oppretter ikke Shopify lenger tilpassede apper i admin, så det finnes to typer tilkobling:',
'Shopify_G_Cred_DevDash' => '{app} (alle butikker som kobles til nå) — {path}. Gi Admin API-tilgangene for det denne butikken synkroniserer, installer appen i butikken, og kopier deretter {clientId} og {clientSecret} fra appens innstillingsside inn i {where}. ERP-systemet bytter dem selv mot et tilgangstoken og fornyer det før det utløper hver 24. time. Client secret signerer også webhooks, så ingenting annet trengs. Appen og butikken må være i samme Shopify-organisasjon.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard-app',
'Shopify_G_Cred_Legacy' => '{app} (opprettet i admin før 2026) — fortsetter å fungere uendret med sitt {token} ({prefix}) og sin {secret} som webhook-signeringshemmelighet. Ikke samme verdi som tokenet, og å forveksle dem er den vanlige grunnen til at webhooks avvises.',
'Shopify_G_Legacy_App' => 'Eldre tilpasset app',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'lagret',
'Shopify_G_Missing_Refused' => 'mangler — leveranser vil bli avvist',
'Shopify_G_Where_Data_Desc' => '{path} ERP-lageret hvis beholdning denne butikken selger, og Shopify-lokasjonen beholdningen skrives til. Lagersynkronisering og ordreimport nekter begge å kjøre uten dem.',
'Shopify_G_Currently' => 'Nå: lager {warehouse}, lokasjon {location}',
'Shopify_G_Not_Set_Lower' => 'ikke angitt',
'Shopify_G_Ready' => 'klar',
'Shopify_G_Incomplete' => 'ufullstendig',
'Shopify_G_Manual_Syncs' => 'Synkroniseringer du starter manuelt',
'Shopify_G_Manual_Desc' => 'En synkronisering startet fra {centre} svarer umiddelbart og kjører i bakgrunnen, i korte deler som hver fortsetter der den forrige stoppet. En stor katalog blir aldri avbrutt halvveis av hosting som avslutter lange nettforespørsler (LiteSpeed, nginx, en lastbalanserer), og å lukke siden stopper den ikke. Workeren for det er én cron-linje til:',
'Shopify_G_Cron_Copied' => 'Cron-linje kopiert',
'Shopify_G_Manual_Note' => 'Uten den fullføres en synkronisering fortsatt, men bare mens siden Synkroniseringssenter er åpen: når ingen worker plukker opp en kjøring i løpet av noen sekunder, fører siden den videre selv, én kort forespørsel om gangen. På Windows, bruk Oppgaveplanlegging hvert minutt: programmet {program}, argumentene {args}, startet i {dir}.',
'Shopify_G_Then_Pick' => 'Velg deretter hvordan den holder seg i takt',
'Shopify_G_Right_Away' => 'Umiddelbart',
'Shopify_G_Stock_Live' => 'lager i sanntid',
'Shopify_G_Stock_Not_Live' => 'lager ikke i sanntid',
'Shopify_G_Realtime_Lead' => 'Hver endring sendes når den skjer, i løpet av sekunder. To halvdeler, og de er separate brytere: {webhooks} henter butikkens egne hendelser inn, og {push} sender lager ut.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'umiddelbar lageroverføring',
'Shopify_G_Webhooks_In' => 'Webhooks — butikken → ERP-systemet',
'Shopify_G_Webhooks_Desc' => 'Ordrer, endringer i ordrestatus, og produkt-, kunde- og lagerendringer gjort i Shopify. Åpne butikken og trykk {button} på dens {tab} — trygt å trykke to ganger. Shopify sender til:',
'Shopify_G_Webhooks_Tab' => 'Webhooks-fane',
'Shopify_G_Webhooks_Note' => 'Adressen må kunne nås fra internett over HTTPS — Shopify leverer ikke til {localhost} eller et {test}-domene. Hver leveranse registreres én gang, så Shopifys nye forsøk kan ikke opprette en duplikatordre, og en mislykket kan spilles av på nytt. Leveranser avvises til signeringshemmeligheten fra trinn 1 er lagret.',
'Shopify_G_Instant_Out' => 'Umiddelbar lageroverføring — ERP-systemet → butikken',
'Shopify_G_Setting_Missed' => 'Dette er innstillingen folk overser',
'Shopify_G_Pos_Not_Auto' => 'Et POS-salg når {not} Shopify av seg selv. Hvis dette er av, får butikken først vite det ved neste lageroverføringstrinn — og i det vinduet kan den selge en enhet du allerede har solgt i kassen.',
'Shopify_G_Not' => 'ikke',
'Shopify_G_Tick_Push' => 'Kryss av for {setting} på {where}. Det er hele oppsettet — ingen worker, ingen cron. Hvert salg, hver retur og justering sender da en overføring av bare de produktene, rett etter at salget er lagret, og et salg med tjue linjer koster én overføring, ikke tjue. Kassen venter aldri på den.',
'Shopify_G_This_Store' => 'Denne butikken:',
'Shopify_G_Push_On' => 'på — lager overføres ved endring',
'Shopify_G_Push_Off' => 'av — lager kun etter tidsplan',
'Shopify_G_Push_Note' => 'Bare produkter som allerede har en Shopify-kobling, og bare bevegelser i denne butikkens lager, overføres. Masseoperasjoner — slette et produkt, tilbakestille et lager — skriver lager uten å utløse en hendelse, noe som er en grunn til å beholde det planlagte lagertrinnet også.',
'Shopify_G_Nothing_Install' => 'Ingenting annet å installere',
'Shopify_G_No_Worker_Note' => 'Ingen av halvdelene trenger en kø-worker eller en cron-oppføring. En innkommende webhook håndteres i forespørselen Shopify gjør; en utgående lageroverføring kjører i den samme prosessen som betjente salget, {after} at svaret er sendt tilbake — så kassen venter aldri på Shopify, og en butikk som slutter å svare, gis opp etter ti sekunder og overlates til neste planlagte lageroverføring.',
'Shopify_G_After' => 'etter',
'Shopify_G_Artisan_Note' => 'Ett unntak: en lagerendring gjort av en artisan-kommando har ikke noe svar å komme etter, så den settes i kø på {queue} i stedet. Hvis du vil at også disse skal sendes raskt, tøm den køen:',
'Shopify_G_On_Schedule' => 'Etter tidsplan',
'Shopify_G_On_Lower' => 'på',
'Shopify_G_Off_Lower' => 'av',
'Shopify_G_Scheduled_Lead' => 'Alt kontrolleres på nytt med jevne mellomrom, begge veier. Tregere enn sanntid, men det er det som sender lager ut for butikker som ikke bruker umiddelbar overføring, det som fanger opp en tapt webhook, og den eneste måten å flytte en hel katalog på.',
'Shopify_G_Cron_Entry' => 'Cron-oppføringen',
'Shopify_G_Cron_Entry_Desc' => 'Ingenting planlagt kjører uten den. Én linje, kun denne modulen — legg den til ved siden av det du ellers har valgt å planlegge:',
'Shopify_G_Cron_Note' => 'Hvert femte minutt er den fineste oppløsningen en plan kan bruke, fordi fem minutter er det korteste trinnintervallet. En grovere oppføring blir ganske enkelt minimumet — med {example} kjører et trinn satt til 5 minutter hvert 15. minutt. På Windows, bruk Oppgaveplanlegging: programmet {program}, argumentene {args}, startet i {dir}.',
'Shopify_G_Switch_On_Plan' => 'Slå det på, og velg planen',
'Shopify_G_Plan_Desc' => '{where} Bryteren avgjør om cron i det hele tatt kan handle; planen avgjør hva den gjør. Et {step} er én entitet i én retning med sitt eget intervall — {first}, {second}. Standardintervallet brukes av alle trinn som lar sin egen boks stå tom.',
'Shopify_G_Step_Lower' => 'trinn',
'Shopify_G_Plan_Note' => 'La planen stå tom, så henter butikken ordrer og sender lager med standardintervallet, som er det de fleste butikker ønsker. Ordrer kan bare hentes: Shopify er der en kunde legger inn en.',
'Shopify_G_Schedule_On' => 'tidsplan på',
'Shopify_G_Schedule_Off' => 'tidsplan av — kun manuelt',
'Shopify_G_When_Step_Runs' => 'Når et trinn faktisk kjører',
'Shopify_G_When_Note' => 'Et trinn forfaller når det samme trinnet sist ble {started} for lengre tid siden enn intervallet, lest fra kjøringshistorikken. Så en synkronisering du starter manuelt, utsetter den neste automatiske, og et trinn som stadig mislykkes, prøves på nytt etter intervallet i stedet for ved hvert tikk. Butikkens oversikt viser hvert trinns siste kjøring, neste forfallstid, og årsaken til at det er blokkert når det er det. Kjør den første katalogoverføringen manuelt — med {dryRun} først — før du legger den på en tidsplan.',
'Shopify_G_Started_Lower' => 'startet',
'Shopify_G_Where_Setting' => 'Hvor hver innstilling ligger',
